############################################################ # PG Setup Code ############################################################ $mc27 = CheckboxList([ ["${BM}S_n-S${EM} is going down in absolute value as ${BM}n${EM} increases.$BR", "${BM}S_n-S${EM} is going up in absolute value as ${BM}n${EM} increases.$BR", "${BM}S_n-S${EM} is going up and down in absolute value as ${BM}n${EM} increases.$BR", "${BM}S_n-S${EM} is negative when the partial sum is an underestimate.$BR", "${BM}S_n-S${EM} is positive when the partial sum is an underestimate.$BR", "${BM}S_n-S${EM} is negative when the partial sum is an overestimate.$BR", "${BM}S_n-S${EM} is positive when the partial sum is an overestimate.$BR", "${BM}S_n${EM} alternates back and forth between overestimates and underestimates.$BR", "${BM}S_n${EM} is always an overestimate.$BR", "${BM}S_n${EM} is always an underestimate.$BR" ]], [0,3,6,7] ); $mc = CheckboxList([ ["The absolute value of ${BM}S_n-S${EM} is always smaller than the absolute value of ${BM}a_n${EM}.$BR", "The absolute value of ${BM}S_n-S${EM} is sometimes smaller than the absolute value of ${BM}a_n${EM}.$BR", "The absolute value of ${BM}S_n-S${EM} is always larger than the absolute value of ${BM}a_n${EM}.$BR", "When ${BM}S_n-S${EM} is negative, ${BM}a_n${EM} is positive.$BR", "When ${BM}S_n-S${EM} is positive, ${BM}a_n${EM} is positive.$BR", "When ${BM}S_n-S${EM} is negative, ${BM}a_n${EM} is negative.$BR", "When ${BM}S_n-S${EM} is positive, ${BM}a_n${EM} is negative.$BR", "${BM}S_n+a_n = S_{n+1}${EM}.$BR", ]], [0,3,6,7] ); Context("LimitedNumeric");
